final class PublisherTests: XCTestCase, Observer {   // the test case is the double
    private var seen: [String] = []
    func onEvent(_ e: String) { seen.append(e) }      // records the callback

    func testPublishesOnce() {
        Publisher(self).change("x")                   // install the test itself
        XCTAssertEqual(seen, ["x"])
    }
}
